package com.tuap.backend.auth;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.*; import com.tuap.backend.dominio.entidades.AuthIdentity; import com.tuap.backend.persistencia.AuthIdentityDAO;
class AuthIdentityServiceTest { AuthIdentityDAO dao=mock(AuthIdentityDAO.class); IdentityResolver users=mock(IdentityResolver.class); AuthIdentityService service=new AuthIdentityService(dao,users,Clock.fixed(Instant.parse("2026-01-01T00:00:00Z"),ZoneOffset.UTC)); AuthenticatedUser a=new AuthenticatedUser(UUID.randomUUID(),"a@test",Role.CLIENTE), b=new AuthenticatedUser(UUID.randomUUID(),"b@test",Role.ENTRENADOR);
 @Test void localIsStableAndIdempotent(){when(dao.existsByUserIdAndRoleAndProviderAndActiveTrue(a.userId(),a.role(),AuthProvider.LOCAL)).thenReturn(false);when(dao.findByProviderAndProviderSubject(AuthProvider.LOCAL,a.userId().toString())).thenReturn(Optional.empty());service.ensureLocalIdentity(a);verify(dao).save(argThat(i->i.getProvider()==AuthProvider.LOCAL&&i.getProviderSubject().equals(a.userId().toString())));}
 @Test void externalLinkIsIdempotentForSameAccountButCannotBeHijacked(){AuthIdentity same=new AuthIdentity(a.userId(),a.role(),AuthProvider.GOOGLE,"sub","same@test",Instant.now());when(dao.findByProviderAndProviderSubject(AuthProvider.GOOGLE,"sub")).thenReturn(Optional.of(same));assertSame(same,service.linkIdentity(a,AuthProvider.GOOGLE,"sub","other@test"));assertThrows(AuthIdentityConflictException.class,()->service.linkIdentity(b,AuthProvider.GOOGLE,"sub","other@test"));}
 @Test void emailIsNotLookupAuthority(){AuthIdentity one=new AuthIdentity(a.userId(),a.role(),AuthProvider.GOOGLE,"one","same@test",Instant.now());AuthIdentity two=new AuthIdentity(b.userId(),b.role(),AuthProvider.GOOGLE,"two","same@test",Instant.now());when(dao.findByProviderAndProviderSubject(AuthProvider.GOOGLE,"one")).thenReturn(Optional.of(one));when(dao.findByProviderAndProviderSubject(AuthProvider.GOOGLE,"two")).thenReturn(Optional.of(two));when(users.findByIdAndRole(a.userId(),a.role())).thenReturn(Optional.of(a));when(users.findByIdAndRole(b.userId(),b.role())).thenReturn(Optional.of(b));assertEquals(a,service.findExternalIdentity(AuthProvider.GOOGLE,"one").orElseThrow());assertEquals(b,service.findExternalIdentity(AuthProvider.GOOGLE,"two").orElseThrow());}
 @Test void cannotDeactivateLastMethod(){AuthIdentity google=new AuthIdentity(a.userId(),a.role(),AuthProvider.GOOGLE,"sub",null,Instant.now());when(dao.findByUserIdAndRoleAndActiveTrue(a.userId(),a.role())).thenReturn(List.of(google));when(dao.countByUserIdAndRoleAndActiveTrue(a.userId(),a.role())).thenReturn(1L);assertThrows(LastAuthIdentityException.class,()->service.deactivateIdentity(a,AuthProvider.GOOGLE));}
}
